  "src/client/main.client.ts": "import { Workspace } from \"@rbxts/services\";\nimport { Remotes, waitRemoteEvent, type PlayerStats } from \"shared/net\";\nimport { Hud } from \"ui/Hud\";\n\n/** Client bootstrap: HUD + world loading overlay. */\nconst hud = new Hud();\nwaitRemoteEvent(Remotes.StatsChanged).OnClientEvent.Connect((stats) => hud.setStats(stats as PlayerStats));\nwaitRemoteEvent(Remotes.Notify).OnClientEvent.Connect((text) => hud.notify(text as string));\nwaitRemoteEvent(Remotes.WorldProgress).OnClientEvent.Connect((stage, done, total) => hud.setLoading(stage as string, done as number, total as number));\n\nconst ready = () => hud.hideLoading();\nif (Workspace.GetAttribute(\"WorldReady\") === true) ready();\nelse {\n\tconst conn = Workspace.GetAttributeChangedSignal(\"WorldReady\").Connect(() => {\n\t\tif (Workspace.GetAttribute(\"WorldReady\") === true) {\n\t\t\tconn.Disconnect();\n\t\t\tready();\n\t\t}\n\t});\n\ttask.delay(45, ready);\n}\n",
  "src/server/main.server.ts": "import { Workspace } from \"@rbxts/services\";\nimport { buildWorld, loadBake } from \"world/WorldBuilder\";\nimport * as PlayerData from \"systems/PlayerData\";\nimport * as Survival from \"systems/Survival\";\nimport * as Collectibles from \"systems/Collectibles\";\nimport { getRemoteEvent, Remotes } from \"shared/net\";\n\n/**\n * Server bootstrap: build the world (unless prebaked into the place), then start gameplay systems.\n */\nconst progress = getRemoteEvent(Remotes.WorldProgress);\nPlayerData.start();\n\nconst prebaked = Workspace.GetAttribute(\"WorldPrebaked\") === true;\nif (!prebaked) {\n\tconst bake = loadBake();\n\tprint(`[WorldForge] building world \"${bake.meta.specName}\" ${bake.meta.version} (${bake.placementCount} placements)`);\n\tconst report = buildWorld(bake, {\n\t\tonProgress: (stage, done, total) => progress.FireAllClients(stage, done, total),\n\t});\n\tprint(`[WorldForge] world ready: ${report.placements} placements, ${report.terrainChunks} terrain chunks in ${string.format(\"%.1f\", report.seconds)}s`);\n} else {\n\tWorkspace.SetAttribute(\"WorldReady\", true);\n}\n\nSurvival.start();\nCollectibles.start();\n",
